// Ağaç görünümünün saf arama mantığı: eşleşmeler, açılacak üst düğümler, görünür düğümler. React içermez; test doğrudan bunu okur.
import { text } from "@snn/abacus-core";

export interface TreeNode {
  /** Kalıcı kimlik. */
  id: string;
  label: string;
  /** Adın yanında soluk yazılan ek bilgi, örneğin kod ya da ağırlık. Aramaya dahildir. */
  meta?: string;
  children?: TreeNode[];
}

export interface TreeSearch {
  /** Sorguya uyan düğümler. */
  matches: Set<string>;
  /** Eşleşmelerin bütün üstleri: arama sırasında açık durur. */
  expand: Set<string>;
  /** Eşleşmeler ve üstleri: arama sırasında yalnız bunlar görünür. */
  visible: Set<string>;
}

/**
 * Sorgudaki her kelime düğümün adında ya da ek bilgisinde geçiyorsa düğüm eşleşir (Türkçe harfe duyarsız: "sut" "Süt"ü bulur).
 * Sorgu boşsa null döner: ağaç kullanıcının açtığı gibi görünür.
 */
export function searchTree(nodes: TreeNode[], query: string): TreeSearch | null {
  const words = text.searchKey(query.trim()).split(/\s+/).filter(Boolean);
  if (!words.length) return null;
  const result: TreeSearch = { matches: new Set(), expand: new Set(), visible: new Set() };
  const walk = (node: TreeNode, path: string[]): boolean => {
    const key = text.searchKey(`${node.label} ${node.meta ?? ""}`);
    const own = words.every(word => key.includes(word));
    let below = false;
    for (const child of node.children ?? []) below = walk(child, [...path, node.id]) || below;
    if (own) result.matches.add(node.id);
    if (own || below) result.visible.add(node.id);
    if (below) result.expand.add(node.id);
    return own || below;
  };
  for (const node of nodes) walk(node, []);
  return result;
}

/** Bir düğümün üstlerinin kimlikleri, kökten başlayarak. Seçili düğümü açık göstermek için. */
export function ancestorsOf(nodes: TreeNode[], id: string): string[] {
  const find = (list: TreeNode[], path: string[]): string[] | null => {
    for (const node of list) {
      if (node.id === id) return path;
      const found = find(node.children ?? [], [...path, node.id]);
      if (found) return found;
    }
    return null;
  };
  return find(nodes, []) ?? [];
}

/** Adın sorguyla eşleşen ilk parçası [başlangıç, bitiş]; Türkçe harf dönüşümü uzunluğu değiştiriyorsa vurgulanmaz (null). */
export function matchRange(label: string, query: string): [number, number] | null {
  const word = text.searchKey(query.trim()).split(/\s+/).filter(Boolean)[0];
  if (!word) return null;
  const key = text.searchKey(label);
  if (key.length !== label.length) return null;
  const start = key.indexOf(word);
  return start === -1 ? null : [start, start + word.length];
}

/* Ağaç: her satır iki düğmedir. Soldaki ok alt kalemleri açar, ad satırı seçer; ikisi ayrı odaklanır. */
.tree { display: flex; min-width: 0; flex-direction: column; gap: var(--space-3); color: var(--foreground); font-size: var(--text-sm); line-height: var(--leading-body); }
.search { display: flex; flex-direction: column; gap: var(--space-2); }
.count { margin: 0; color: var(--text-secondary); font-size: var(--text-xs); }
.list { margin: 0; padding: 0; list-style: none; }
.row { --indent: calc(var(--depth, 0) * 20px); display: flex; min-height: 36px; align-items: center; gap: 2px; padding-left: var(--indent); border-radius: var(--radius-control); transition: background-color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .row:hover { background: var(--surface-muted); } }
.row[data-selected] { background: var(--accent-subtle); }
.toggle, .spacer { flex: none; width: 28px; height: 28px; }
.toggle { display: grid; place-items: center; border: 0; border-radius: 999px; padding: 0; background: transparent; color: var(--text-muted); cursor: pointer; }
.toggle[aria-disabled] { cursor: default; }
@media (hover: hover) and (pointer: fine) { .toggle:not([aria-disabled]):hover { color: var(--foreground); } }
.chevron { display: inline-flex; }
.select { display: flex; min-width: 0; flex: 1; align-items: baseline; gap: var(--space-2); border: 0; border-radius: var(--radius-control); padding: 6px var(--space-2); background: transparent; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.name { min-width: 0; overflow-wrap: anywhere; }
.name[data-matched] { font-weight: 500; }
.row[data-selected] .name { font-weight: 500; }
.meta { flex: none; margin-left: auto; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.mark { border-radius: 3px; background: var(--accent-subtle); color: inherit; box-shadow: 0 0 0 1px var(--accent-subtle); }
@media (prefers-reduced-motion: reduce) { .row { transition: none; } }

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ChevronRight } from "lucide-react";
import { motionTokens } from "../lib/motion-tokens";
import { SearchField } from "../search-field/search-field";
import { ancestorsOf, matchRange, searchTree, type TreeNode, type TreeSearch } from "./tree-view-search";
import styles from "./tree-view.module.css";

export type { TreeNode } from "./tree-view-search";

export interface TreeViewProps {
  nodes: TreeNode[];
  /** Ağacı yardımcı teknolojiye adlandırır, örneğin "TÜFE sınıflaması". */
  label: string;
  /** Denetimli seçili düğüm. */
  selected?: string | null;
  defaultSelected?: string | null;
  onSelect?: (node: TreeNode) => void;
  /** Üstte arama kutusu. Varsayılan açık. */
  searchable?: boolean;
  searchLabel?: string;
  searchPlaceholder?: string;
  /** Başta açık düğümler; "all" hepsini açar. Seçili düğümün üstleri her zaman açık başlar. */
  defaultExpanded?: string[] | "all";
  className?: string;
}

const collectIds = (nodes: TreeNode[]): string[] => nodes.flatMap(node => node.children?.length ? [node.id, ...collectIds(node.children)] : []);

function Label({ text: label, query, matched }: { text: string; query: string; matched: boolean }) {
  const range = matched ? matchRange(label, query) : null;
  if (!range) return <>{label}</>;
  return <>{label.slice(0, range[0])}<mark className={styles.mark}>{label.slice(range[0], range[1])}</mark>{label.slice(range[1])}</>;
}

/** İç içe liste: açma düğmesi ile seçim düğmesi ayrıdır. Arama eşleşen düğümün bütün üstlerini açar ve eşleşme sayısını yazar. */
export function TreeView({ nodes, label, selected: selectedProp, defaultSelected = null, onSelect, searchable = true, searchLabel = "Ara", searchPlaceholder = "Kalem ara", defaultExpanded, className }: TreeViewProps) {
  const reduce = !!useReducedMotion();
  const [ownSelected, setOwnSelected] = useState(defaultSelected);
  const selected = selectedProp !== undefined ? selectedProp : ownSelected;
  const [open, setOpen] = useState<Set<string>>(() => new Set([...(defaultExpanded === "all" ? collectIds(nodes) : defaultExpanded ?? []), ...(selected ? ancestorsOf(nodes, selected) : [])]));
  const [query, setQuery] = useState("");
  const search = searchTree(nodes, query);
  const toggle = (id: string) => setOpen(current => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const choose = (node: TreeNode) => { if (selectedProp === undefined) setOwnSelected(node.id); onSelect?.(node); };

  const renderList = (list: TreeNode[], depth: number, search: TreeSearch | null) => <ul className={styles.list} role={depth === 0 ? "list" : undefined}>
    {list.filter(node => !search || search.visible.has(node.id)).map(node => {
      const parent = !!node.children?.length;
      const expanded = parent && (search ? search.expand.has(node.id) : open.has(node.id));
      const matched = !!search?.matches.has(node.id);
      return <li key={node.id}>
        <div className={styles.row} style={{ "--depth": depth } as React.CSSProperties} data-selected={selected === node.id || undefined}>
          {parent
            ? <button type="button" className={styles.toggle} aria-expanded={expanded} aria-label={`${node.label}: alt kalemleri ${expanded ? "kapat" : "aç"}`} aria-disabled={search ? true : undefined} onClick={() => { if (!search) toggle(node.id); }}>
                <motion.span className={styles.chevron} initial={false} animate={{ rotate: expanded ? 90 : 0 }} transition={reduce ? { duration: 0 } : motionTokens.spring.snappy}><ChevronRight size={16} strokeWidth={1.75} aria-hidden="true" /></motion.span>
              </button>
            : <span className={styles.spacer} aria-hidden="true" />}
          <button type="button" className={styles.select} aria-pressed={selected === node.id} onClick={() => choose(node)}>
            <span className={styles.name} data-matched={matched || undefined}><Label text={node.label} query={query} matched={matched} /></span>
            {node.meta && <span className={styles.meta}>{node.meta}</span>}
          </button>
        </div>
        {expanded && renderList(node.children!, depth + 1, search)}
      </li>;
    })}
  </ul>;

  return <div className={[styles.tree, className].filter(Boolean).join(" ")} role="group" aria-label={label}>
    {searchable && <div className={styles.search}>
      <SearchField label={searchLabel} placeholder={searchPlaceholder} value={query} onValueChange={setQuery} />
      {search && <p className={styles.count} role="status">{search.matches.size ? `${search.matches.size} eşleşme` : "Eşleşme yok"}</p>}
    </div>}
    {renderList(nodes, 0, search)}
  </div>;
}

export default TreeView;
